import { util } from '@aws-appsync/utils';

const VP_TABLE = 'LMASA-AISTACK-4VKHCQQY3CJR-VirtualParticipant';
const SHARE_INDEX_TABLE = 'LMASA-VirtualParticipantShareIndex';

// Matches the live VTL exactly: unshare always clears SharedWith entirely
// (the input list is ignored for the write itself, only echoed back in the
// response), regardless of which grantees were passed in. We remove every
// existing grantee's mirror entry for this VP id.
export function request(ctx) {
  const id = ctx.args.input.id;
  const oldRaw = ctx.stash.oldSharedWith ? ctx.stash.oldSharedWith : '';
  const oldList = oldRaw
    .split(',')
    .map((s) => s.trim())
    .filter((s) => s.length > 0);

  const transactItems = [
    {
      table: VP_TABLE,
      operation: 'UpdateItem',
      key: util.dynamodb.toMapValues({ id }),
      update: {
        expression: 'SET SharedWith = :val',
        expressionValues: util.dynamodb.toMapValues({ ':val': '' }),
      },
    },
  ];

  for (const grantee of oldList) {
    transactItems.push({
      table: SHARE_INDEX_TABLE,
      operation: 'UpdateItem',
      key: util.dynamodb.toMapValues({ PK: `u#${grantee}` }),
      update: {
        expression: 'DELETE VpIds :ids',
        expressionValues: { ':ids': util.dynamodb.toStringSet([id]) },
      },
    });
  }

  return { operation: 'TransactWriteItems', transactItems };
}

export function response(ctx) {
  return {
    id: ctx.args.input.id,
    SharedWith: ctx.args.input.SharedWith,
  };
}
